-- Sincronização das Sequences (Autoincrement) do PostgreSQL
SELECT setval(pg_get_serial_sequence('"User"', 'id'), coalesce((SELECT max(id) FROM "User"), 1));
SELECT setval(pg_get_serial_sequence('"Course"', 'id'), coalesce((SELECT max(id) FROM "Course"), 1));
SELECT setval(pg_get_serial_sequence('"Room"', 'id'), coalesce((SELECT max(id) FROM "Room"), 1));
